-- 같은 포지션 카드끼리 기준 다리 · 팔 맞추기 62개 (D-75). 그사이 고친 카드는 건드리지 않는다.
update public.techniques set steps = array['내 오른손은 상대 왼쪽 깃, 왼손은 상대 오른쪽 소매를 잡고 상대를 당긴다','내 오른발을 상대 왼쪽 골반에, 또는 왼발을 상대 오른쪽 이두에 대며 앉는다','앉으며 바로 내 왼다리로 상대 오른다리 바깥에 데라히바 훅을 걸거나 왼발로 스파이더를 잡는다','상대 균형을 흔들며 스윕을 노린다']::text[] where slug = 'standing-guard-pull' and owner_id is null and steps = array['내 오른손은 상대 왼쪽 깃, 왼손은 상대 오른쪽 소매를 잡고 상대를 당긴다','내 오른발을 상대 왼쪽 골반에, 또는 왼발을 상대 오른쪽 이두에 대며 앉는다','앉으며 바로 내 오른다리로 상대 왼다리에 데라히바 훅을 걸거나 왼발로 스파이더를 잡는다','상대 균형을 흔들며 스윕을 노린다']::text[];
update public.techniques set steps = array['뒤에서 내 오른팔은 상대 오른쪽 어깨 위, 왼팔은 왼쪽 겨드랑이 밑으로 시트벨트를 꽉 잡는다','내 왼발로 상대 왼쪽 무릎 뒤를 눌러 무릎을 꺾는다','상대를 뒤로 끌어당기며 언더훅 쪽인 내 왼쪽 엉덩이부터 비스듬히 바닥에 내린다','앉는 순간 위쪽 오른발, 아래쪽 왼발 순서로 상대 허벅지 안쪽에 훅을 넣는다','백 컨트롤로 끝난다']::text[] where slug = 'takedown-to-grounded-back-control' and owner_id is null and steps = array['뒤에서 내 오른팔은 상대 오른쪽 어깨 위, 왼팔은 왼쪽 겨드랑이 밑으로 시트벨트를 꽉 잡는다','내 오른발로 상대 오른쪽 무릎 뒤를 눌러 무릎을 꺾는다','상대를 뒤로 끌어당기며 내 오른쪽 엉덩이부터 비스듬히 바닥에 내린다','앉는 순간 오른발, 왼발 순서로 상대 허벅지 안쪽에 훅을 넣는다','백 컨트롤로 끝난다']::text[];
update public.techniques set steps = array['내 왼손으로 상대 오른쪽 손목을 내 가슴에 붙이고, 내 오른손으로 상대 오른팔 삼두를 당겨 고정한다','내 오른발을 상대 왼쪽 골반에 대고 밀어 몸을 돌려 상대와 직각이 된다','내 왼다리를 상대 얼굴 위로 넘기고, 오른다리는 상대 등(오른쪽 옆구리)에 붙여 조인다','무릎을 모으고 상대 오른손 엄지가 위로 향한 채 엉덩이를 천천히 들어 팔꿈치를 편다']::text[] where slug = 'closed-guard-armbar' and owner_id is null and steps = array['내 왼손으로 상대 오른쪽 손목을 내 가슴에 붙이고, 내 오른손으로 상대 오른팔 삼두를 당겨 고정한다','내 오른발을 상대 왼쪽 골반에 대고 밀어 몸을 돌려 상대와 직각이 된다','그 오른다리를 상대 얼굴 위로 넘기고, 왼다리는 상대 등(오른쪽 옆구리)에 붙여 조인다','무릎을 모으고 상대 오른손 엄지가 위로 향한 채 엉덩이를 천천히 들어 팔꿈치를 편다']::text[];
update public.techniques set steps = array['상대가 상체를 세우고 내 가슴을 누를 때 — 가드를 풀고 내 오른손으로 뒤 바닥을 짚으며 앉아 일어난다','내 왼팔을 상대 오른쪽 어깨 위로 넘겨 상대 오른팔 삼두(팔 뒤)를 감싼다','엉덩이를 높이 들어 상대 오른쪽 어깨를 쳐서 상대를 내 오른쪽으로 넘긴다','넘어가면 다리를 돌려 마운트. 상대가 왼손을 바닥에 짚으면 기무라, 앞으로 밀면 길로틴으로 잇는다']::text[] where slug = 'hip-bump-sweep' and owner_id is null and steps = array['상대가 상체를 세우고 내 가슴을 누를 때 — 가드를 풀고 내 오른손으로 뒤 바닥을 짚으며 앉아 일어난다','내 왼팔을 상대 오른쪽 어깨 위로 넘겨 상대 오른팔 삼두(팔 뒤)를 감싼다','엉덩이를 높이 들어 상대 오른쪽 어깨를 쳐서 상대를 내 오른쪽으로 넘긴다','넘어가면 다리를 돌려 마운트. 상대가 오른손을 바닥에 짚으면 기무라, 앞으로 밀면 길로틴으로 잇는다']::text[];
update public.techniques set steps = array['트라이앵글에서 상대가 갇힌 오른팔을 아래로 빼려 하면 다리를 풀고 내 왼다리를 상대 오른쪽 어깨 위로 넘긴다','상대 오른쪽 옆으로 앉아 올라온다','내 오른팔로 상대 허리를 감싸 앞구르기를 막는다','엉덩이를 앞으로 밀며 천천히 상대 오른쪽 어깨를 꺾는다','탭하면 바로 푼다']::text[] where slug = 'triangle-to-omoplata' and owner_id is null and steps = array['트라이앵글에서 상대가 갇힌 오른팔을 아래로 빼려 하면 다리를 풀고 내 왼다리를 상대 오른쪽 어깨 위로 넘긴다','상대 오른쪽 옆으로 앉아 올라온다','내 왼팔로 상대 허리를 감싸 앞구르기를 막는다','엉덩이를 앞으로 밀며 천천히 상대 오른쪽 어깨를 꺾는다','탭하면 바로 푼다']::text[];
update public.techniques set steps = array['앉은 가드에서 내 오른손으로 상대 왼쪽 발목(뒤꿈치)을 잡고 왼손으로 상대 오른쪽 소매를 잡는다','내 오른발을 상대 왼쪽 골반에 대고 민다','내 왼발로 상대 오른다리 오금을 걸어 당긴다','골반을 밀고 발목과 오금을 당겨 뒤로 눕힌 뒤, 왼쪽 발목을 놓지 않고 바로 일어나 패스 자세로 간다']::text[] where slug = 'tripod-sweep' and owner_id is null and steps = array['앉은 가드에서 내 왼손으로 상대 오른쪽 발목(뒤꿈치)을 잡고 오른손으로 상대 왼쪽 소매를 잡는다','내 왼발을 상대 오른쪽 골반에 대고 민다','내 오른발로 상대 왼다리 오금을 걸어 당긴다','골반을 밀고 발목과 오금을 당겨 뒤로 눕힌 뒤, 오른쪽 발목을 놓지 않고 바로 일어나 패스 자세로 간다']::text[];
update public.techniques set steps = array['트라이포드와 같은 그립(내 오른손 상대 왼쪽 발목 · 왼손 상대 오른쪽 소매)에서 시작한다','상대 왼쪽 골반에 댄 내 오른발은 그대로 밀고, 오금을 걸던 왼발을 바닥으로 내린다','내린 왼발로 상대 오른쪽 발목 바깥을 낫처럼 걸어 안쪽으로 쓸면서 골반을 밀고 발목을 당긴다','상대가 옆으로 넘어지면 왼쪽 발목을 놓지 않고 일어나 패스 자세로 간다']::text[] where slug = 'sickle-sweep' and owner_id is null and steps = array['트라이포드와 같은 그립(내 왼손 상대 오른쪽 발목 · 오른손 상대 왼쪽 소매)에서 시작한다','상대 오른쪽 골반에 댄 내 왼발은 그대로 밀고, 오금을 걸던 오른발을 바닥으로 내린다','내린 오른발로 상대 왼쪽 발목 바깥을 낫처럼 걸어 안쪽으로 쓸면서 골반을 밀고 발목을 당긴다','상대가 옆으로 넘어지면 오른쪽 발목을 놓지 않고 일어나 패스 자세로 간다']::text[];
update public.techniques set steps = array['K 가드에서 내 왼팔로 상대 오른쪽 발목을 감싸 겨드랑이에 끼운다','상대 오른쪽 허벅지 안쪽에 건 내 왼다리로 그 허벅지를 들며 엉덩이를 그 밑으로 넣는다','바깥에 세웠던 내 오른다리를 상대 두 다리 사이로 옮겨 오른발을 상대 왼쪽 골반에 댄다','들어 올린 왼다리로 상대 오른쪽 무릎 뒤를 바깥에서 감는다','싱글 레그 X 가드로 끝난다']::text[] where slug = 'k-guard-to-single-leg-x' and owner_id is null and steps = array['K 가드에서 내 왼팔로 상대 오른쪽 발목을 감싸 겨드랑이에 끼운다','상대 다리 사이에 넣은 내 오른다리로 상대 오른쪽 허벅지를 들며 엉덩이를 그 밑으로 넣는다','내 오른발을 상대 왼쪽 골반에 댄다','내 왼다리로 상대 오른쪽 무릎 뒤를 감는다','싱글 레그 X 가드로 끝난다']::text[];
update public.techniques set steps = array['상대가 내 왼발에 앵클락을 걸었을 때, 바로 앉아 내 발목을 감은 상대 오른팔을 잡아 못 눕게 한다','왼발 발끝을 위로 세워 발목이 안 펴지게 한다','내 오른발로 상대 엉덩이나 발목을 밀며 왼다리를 뺀다','위로 올라가 패스한다']::text[] where slug = 'ankle-lock-escape' and owner_id is null and steps = array['상대가 내 오른발에 앵클락을 걸었을 때, 바로 앉아 내 발목을 감은 상대 왼팔을 잡아 못 눕게 한다','오른발 발끝을 위로 세워 발목이 안 펴지게 한다','내 왼발로 상대 엉덩이나 발목을 밀며 오른다리를 뺀다','위로 올라가 패스한다']::text[];
update public.techniques set steps = array['상대가 내 왼발에 앵클락을 걸었을 때, 왼쪽 무릎을 굽히고 왼발 발끝을 몸 쪽으로 세워 발목을 지킨다','내 두 손으로 내 왼발 뒤꿈치를 잡은 상대 손을 떼어낸다','내 오른발로 상대 다리를 밀며 왼쪽 무릎을 상대 다리 사이에서 빼낸다','뒤로 물러나 서거나 발을 상대 골반에 대 거리를 둔다']::text[] where slug = 'knee-extraction' and owner_id is null and steps = array['상대가 내 오른발에 앵클락을 걸었을 때, 오른쪽 무릎을 굽히고 오른발 발끝을 몸 쪽으로 세워 발목을 지킨다','내 두 손으로 내 오른발 뒤꿈치를 잡은 상대 손을 떼어낸다','내 왼발로 상대 다리를 밀며 오른쪽 무릎을 상대 다리 사이에서 빼낸다','뒤로 물러나 서거나 발을 상대 골반에 대 거리를 둔다']::text[];
update public.techniques set steps = array['웜 가드(상대 오른쪽 라펠을 상대 오른다리 뒤로 돌려 내 왼다리에 감음)에서 라펠 끝을 왼손으로 옮겨 당긴다','감은 내 왼발로 상대 오른쪽 골반을 밀며 내 오른손으로 상대 왼쪽 발목이나 바지를 잡는다','라펠을 당기며 상대 왼다리를 들어 묶인 오른다리 쪽(상대 오른쪽)으로 넘긴다','라펠을 놓지 않고 따라 올라가 사이드나 마운트로 간다']::text[] where slug = 'worm-guard-sweep' and owner_id is null and steps = array['웜 가드(상대 왼쪽 라펠을 상대 왼다리 뒤로 돌려 내 오른다리에 감음)에서 오른손으로 라펠을 당긴다','내 오른발로 상대 왼쪽 골반을 밀며 내 왼손으로 상대 오른쪽 발목이나 바지를 잡는다','라펠을 당기며 상대 오른다리를 들어 묶인 왼다리 쪽(상대 왼쪽)으로 넘긴다','라펠을 놓지 않고 따라 올라가 사이드나 마운트로 간다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽 라펠을 빼려 하면 내 오른손으로 오른쪽 깃을 가슴에 눌러 못 빼게 막는다','이미 감겼으면 엉덩이를 뒤로 빼고 등을 세워 숙여지지 않게 한다','라펠 끝을 쥔 상대 손목을 내 두 손으로 잡아 손가락을 떼어낸다','풀린 라펠을 내 오른다리에서 빼내 몸 쪽에 붙이고 바로 패스 그립을 잡는다']::text[] where slug = 'defend-worm-guard-posture' and owner_id is null and steps = array['상대가 내 왼쪽 라펠을 빼려 하면 내 왼손으로 왼쪽 깃을 가슴에 눌러 못 빼게 막는다','이미 감겼으면 엉덩이를 뒤로 빼고 등을 세워 숙여지지 않게 한다','라펠 끝을 쥔 상대 손목을 내 두 손으로 잡아 손가락을 떼어낸다','풀린 라펠을 내 왼다리에서 빼내 몸 쪽에 붙이고 바로 패스 그립을 잡는다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽 라펠을 잡았을 때, 내 오른손으로 내 오른쪽 깃을 몸 쪽으로 당겨 느슨하게 한다','라펠을 내 다리와 몸에서 완전히 빼낸다','빼자마자 내 왼손은 상대 오른쪽 무릎, 오른손은 왼쪽 무릎을 잡아 내 왼쪽으로 민다','무릎을 바닥에 눌러 두고 내 오른쪽으로 돌아 상대 왼쪽 사이드 컨트롤로 간다']::text[] where slug = 'lapel-clear-to-toreando' and owner_id is null and steps = array['상대가 내 왼쪽 라펠을 잡았을 때, 내 왼손으로 내 왼쪽 깃을 몸 쪽으로 당겨 느슨하게 한다','라펠을 내 다리와 몸에서 완전히 빼낸다','빼자마자 내 왼손은 상대 오른쪽 무릎, 오른손은 왼쪽 무릎을 잡아 내 왼쪽으로 민다','무릎을 바닥에 눌러 두고 내 오른쪽으로 돌아 상대 왼쪽 사이드 컨트롤로 간다']::text[];
update public.techniques set steps = array['라펠로 상대 오른팔을 상대 몸에 묶어 팔이 아래로 처지게 한다','엉덩이를 내 왼쪽으로 빼며 내 왼다리를 상대 오른팔 위로 넘겨 등 뒤에 건다','두 발을 모아 상대 오른쪽 어깨를 잠그고 내 왼팔을 상대 등 위로 넘겨 허리띠를 잡아 구르지 못하게 한다','앉아 올라오며 상체를 상대 머리 쪽으로 눌러 오른쪽 어깨를 꺾는다']::text[] where slug = 'lapel-omoplata-entry' and owner_id is null and steps = array['라펠로 상대 오른팔을 상대 몸에 묶어 팔이 아래로 처지게 한다','엉덩이를 내 왼쪽으로 빼며 내 왼다리를 상대 오른팔 위로 넘겨 등 뒤에 건다','두 발을 모아 상대 오른쪽 어깨를 잠그고 내 오른손으로 상대 허리띠를 잡아 구르지 못하게 한다','앉아 올라오며 상체를 상대 머리 쪽으로 눌러 오른쪽 어깨를 꺾는다']::text[];
update public.techniques set steps = array['내 왼쪽 깃을 잡은 상대 오른손 그립을 손목을 돌려 먼저 끊는다','내 오른쪽 이두에 댄 상대 왼발을 내 오른손으로 잡아 바닥으로 내린다','내 오른쪽 무릎을 눌러 둔 상대 왼쪽 허벅지 위로 올린다','니슬라이스나 토레안도로 상대 왼쪽 사이드로 간다']::text[] where slug = 'pass-collar-sleeve-guard' and owner_id is null and steps = array['내 왼쪽 깃을 잡은 상대 오른손 그립을 손목을 돌려 먼저 끊는다','내 오른쪽 이두에 댄 상대 왼발을 내 오른손으로 잡아 바닥으로 내린다','내 왼쪽 무릎을 눌러 둔 상대 왼쪽 허벅지 위로 올린다','니슬라이스나 토레안도로 상대 왼쪽 사이드로 간다']::text[];
update public.techniques set steps = array['두 팔꿈치를 몸에 붙이고 손목을 돌려 양 소매 그립을 끊는다','내 오른쪽에 있는 상대 왼발을 내 오른손으로 잡아 바닥으로 내린다','내 오른쪽 무릎을 상대 왼쪽 허벅지 위로 올린다','니슬라이스로 상대 왼쪽 사이드로 간다']::text[] where slug = 'pass-double-sleeve-guard' and owner_id is null and steps = array['두 팔꿈치를 몸에 붙이고 손목을 돌려 양 소매 그립을 끊는다','내 오른쪽에 있는 상대 왼발을 내 오른손으로 잡아 바닥으로 내린다','내 왼쪽 무릎을 상대 왼쪽 허벅지 위로 올린다','니슬라이스로 상대 왼쪽 사이드로 간다']::text[];
update public.techniques set steps = array['내 오른쪽 팔꿈치를 몸에 붙이고 손을 돌려 내 오른쪽 소매 그립을 끊는다','끊은 내 오른손으로 상대 왼발을 잡아 바닥으로 내린다','내 오른쪽 무릎을 상대 왼쪽 허벅지 위로 올린다','니슬라이스나 토레안도로 상대 왼쪽으로 패스한다']::text[] where slug = 'spider-guard-pass' and owner_id is null and steps = array['내 오른쪽 팔꿈치를 몸에 붙이고 손을 돌려 내 오른쪽 소매 그립을 끊는다','끊은 내 오른손으로 상대 왼발을 잡아 바닥으로 내린다','내 왼쪽 무릎을 상대 왼쪽 허벅지 위로 올린다','니슬라이스나 토레안도로 상대 왼쪽으로 패스한다']::text[];
update public.techniques set steps = array['상대 오른다리를 내 양 다리로 감아 발목을 잠근다','내 오른쪽 어깨와 엉덩이를 바닥에 대고 몸을 상대 쪽(내 왼쪽)으로 세운다 — 등이 바닥에 평평하면 진다','내 오른쪽 팔뚝은 상대 목, 왼쪽 팔뚝은 상대 오른쪽 골반에 대어 프레임을 만든다(뼈로)','밀기 전에 먼저 브릿지로 상대 체중을 띄운 뒤 엉덩이를 내 오른쪽(상대에게서 먼 쪽)으로 빼 공간을 만든다']::text[] where slug = 'half-guard-basics' and owner_id is null and steps = array['상대 오른다리를 내 양 다리로 감아 발목을 잠근다','감은 다리 쪽인 내 왼쪽으로 돌아 눕는다 — 등이 바닥에 평평하면 진다','내 오른쪽 팔뚝은 상대 목, 왼쪽 팔뚝은 상대 오른쪽 골반에 대어 프레임을 만든다(뼈로)','밀기 전에 먼저 브릿지로 상대 체중을 띄운 뒤 엉덩이를 상대에게서 멀리 빼 공간을 만든다']::text[];
update public.techniques set steps = array['내 오른쪽 어깨와 엉덩이를 바닥에 대고 오른쪽 팔뚝은 상대 목, 왼쪽 팔뚝은 상대 오른쪽 골반(손바닥 말고 뼈로)','먼저 브릿지로 상대 체중을 띄운다','프레임으로 공간을 지키며 엉덩이를 내 오른쪽으로 뺀다(한 번 더)','위쪽인 내 왼쪽 무릎을 넣거나 왼팔로 언더훅을 잡는다']::text[] where slug = 'half-guard-frames' and owner_id is null and steps = array['내 오른쪽 팔뚝은 상대 목, 왼쪽 팔뚝은 상대 오른쪽 골반(손바닥 말고 뼈로)','먼저 브릿지로 상대 체중을 띄운다','프레임으로 공간을 지키며 엉덩이를 상대에게서 멀리 뺀다(한 번 더)','오른쪽 무릎을 넣거나 왼팔로 언더훅을 잡는다']::text[];
update public.techniques set steps = array['하프가드에서 위쪽인 내 왼쪽 무릎을 상대 배나 골반 앞에 가로로 세운다(낮은 니 쉴드)','아래쪽인 내 오른다리는 상대 오른다리를 계속 감아 둔다','내 오른손은 상대 왼쪽 깃을 잡아 팔을 펴고, 왼손은 상대 오른쪽 소매를 잡아 거리를 지킨다','상대가 오른손으로 내 무릎을 밀어 치우면 내 왼팔을 상대 오른쪽 겨드랑이 아래로 넣어 언더훅']::text[] where slug = 'knee-shield-half-guard' and owner_id is null and steps = array['하프가드에서 위쪽인 내 오른쪽 무릎을 상대 배나 골반 앞에 가로로 세운다(낮은 니 쉴드)','아래쪽인 내 왼다리는 상대 오른다리를 계속 감아 둔다','내 오른손은 내 오른쪽 무릎, 내 왼손은 상대 오른쪽 이두를 잡아 거리를 지킨다','상대가 오른손으로 내 무릎을 밀어 치우면 내 왼팔을 상대 오른쪽 겨드랑이 아래로 넣어 언더훅']::text[];
update public.techniques set steps = array['팔로 먼저 뻗지 말고 위쪽인 내 왼쪽 무릎을 들어 올려 상대 몸을 위로 밀어 공간을 만든다','생긴 공간으로 내 왼팔을 넣어 상대 오른쪽 겨드랑이 아래를 감는다','왼손은 상대 등 위가 아니라 골반 가까이, 왼쪽 팔꿈치는 몸에 붙여 짧게 잡는다','언더훅을 잡으면 머리를 상대 오른쪽 겨드랑이 밑으로 빼고 스윕이나 백 테이크로 간다']::text[] where slug = 'half-guard-underhook' and owner_id is null and steps = array['팔로 먼저 뻗지 말고 내 오른쪽 무릎을 들어 올려 상대 몸을 위로 밀어 공간을 만든다','생긴 공간으로 내 왼팔을 넣어 상대 오른쪽 겨드랑이 아래를 감는다','왼손은 상대 등 위가 아니라 골반 가까이, 왼쪽 팔꿈치는 몸에 붙여 짧게 잡는다','언더훅을 잡으면 머리를 상대 오른쪽 겨드랑이 밑으로 빼고 스윕이나 백 테이크로 간다']::text[];
update public.techniques set steps = array['하프가드에서 내 왼팔로 상대 오른쪽 겨드랑이 아래 언더훅을 잡고 내 오른쪽 어깨와 엉덩이를 바닥에 대 몸을 세운다','머리를 상대 오른쪽 겨드랑이 아래로 넣어 자세를 낮춘다','언더훅한 왼팔로 상대 오른다리를 안아 내리고(또는 오른쪽 발목을 잡고) 중심을 뺏는다','앞으로 밀며 올라와 탑으로 간다']::text[] where slug = 'half-guard-underhook-sweep' and owner_id is null and steps = array['하프가드에서 내 왼팔로 상대 오른쪽 겨드랑이 아래 언더훅을 잡고 내 왼쪽으로 돌아 눕는다','머리를 상대 오른쪽 겨드랑이 아래로 넣어 자세를 낮춘다','언더훅한 왼팔로 상대 오른다리를 안아 내리고(또는 오른쪽 발목을 잡고) 중심을 뺏는다','앞으로 밀며 올라와 탑으로 간다']::text[];
update public.techniques set steps = array['내 왼팔로 언더훅을 잡고 내 오른쪽 어깨와 엉덩이를 바닥에 댄 채 머리를 상대 오른쪽 겨드랑이 아래로 뺀다','무릎을 세워 상대 오른쪽에서 등 뒤로 돌아 올라온다(도그파이트)','내 왼손으로 상대 허리띠나 허리를 잡고 가슴을 상대 등에 붙인다','훅을 넣고 시트벨트를 잡아 백 컨트롤을 완성한다']::text[] where slug = 'half-guard-back-take' and owner_id is null and steps = array['내 왼팔로 언더훅을 잡고 내 왼쪽으로 돌아 머리를 상대 오른쪽 겨드랑이 아래로 뺀다','무릎을 세워 상대 오른쪽에서 등 뒤로 돌아 올라온다(도그파이트)','내 왼손으로 상대 허리띠나 허리를 잡고 가슴을 상대 등에 붙인다','훅을 넣고 시트벨트를 잡아 백 컨트롤을 완성한다']::text[];
update public.techniques set steps = array['내 오른쪽 팔뚝은 상대 목, 왼쪽 팔뚝은 상대 오른쪽 골반에 대어 프레임을 만든다','브릿지 → 엉덩이를 내 오른쪽으로 빼기(쉬림프)를 한 번이 아니라 두 번 한다','위쪽인 내 왼쪽 무릎을 상대 배 앞으로 가져온다','감던 오른다리를 빼 상대 왼쪽 허리 위로 넘기고 왼다리도 상대 오른쪽 허리를 감아 클로즈드 가드나 버터플라이']::text[] where slug = 'half-guard-recovery' and owner_id is null and steps = array['내 오른쪽 팔뚝은 상대 목, 왼쪽 팔뚝은 상대 오른쪽 골반에 대어 프레임을 만든다','브릿지 → 엉덩이를 상대에게서 멀리 빼기(쉬림프)를 한 번이 아니라 두 번 한다','내 오른쪽 무릎을 상대 배 앞으로 가져온다','내 왼다리를 상대 오른쪽 허리 위로 넘겨 클로즈드 가드나 버터플라이로 돌아온다']::text[];
update public.techniques set steps = array['상대가 오른손으로 바닥을 짚으면 내 왼손으로 그 손목을 잡는다','상체를 일으켜 내 오른팔로 상대 오른쪽 윗팔을 위에서 감아 내 왼쪽 손목을 잡는다(8자 그립)','내 오른쪽 엉덩이를 바닥에 댄 채 상체를 내 왼쪽으로 틀어 상대 오른쪽 팔꿈치를 내 가슴에 붙인다','상대 오른손을 상대 등 쪽으로 천천히 돌리고, 안 되면 스윕이나 백으로 잇는다']::text[] where slug = 'kimura-half-guard' and owner_id is null and steps = array['상대가 오른손으로 바닥을 짚으면 내 왼손으로 그 손목을 잡는다','내 오른팔로 상대 오른쪽 윗팔을 위에서 감아 내 왼쪽 손목을 잡는다(8자 그립)','내 왼쪽으로 몸을 돌려 상대 오른쪽 팔꿈치를 내 가슴에 붙인다','상대 오른손을 상대 등 쪽으로 천천히 돌리고, 안 되면 스윕이나 백으로 잇는다']::text[];
update public.techniques set steps = array['니 쉴드인 내 왼쪽 무릎을 상대 가슴이나 어깨 높이로 올린다','아래쪽인 내 오른다리는 상대 오른다리를 감는다','내 오른팔로 상대 머리를 밀어 프레임을 만든다','내 왼손으로 상대 오른쪽 소매나 깃을 잡고 스윕 · 회복을 노린다']::text[] where slug = 'z-guard' and owner_id is null and steps = array['니 쉴드인 내 오른쪽 무릎을 상대 가슴이나 어깨 높이로 올린다','아래쪽인 내 왼다리는 상대 오른다리를 감는다','내 오른팔로 상대 머리를 밀어 프레임을 만든다','내 왼손으로 상대 오른쪽 소매나 깃을 잡고 스윕 · 회복을 노린다']::text[];
