update public.techniques set steps = array['니 쉴드(내 왼쪽 무릎)로 상대를 밀어 거리를 만들고 엉덩이를 내 오른쪽으로 뺀다','감았던 내 오른다리를 빼내 상대 왼쪽 허리 위로 넘긴다','니 쉴드였던 왼다리도 상대 오른쪽 허리 뒤로 넘겨 두 발을 잠근다','클로즈드 가드에서 상대 자세를 무너뜨린다']::text[] where slug = 'knee-shield-to-closed-guard' and owner_id is null and steps = array['니 쉴드(내 오른쪽 무릎)로 상대를 밀어 거리를 만들고 엉덩이를 상대에게서 멀리 뺀다','감았던 내 왼다리를 빼내 상대 오른쪽 허리 위로 넘긴다','니 쉴드였던 오른다리도 상대 왼쪽 허리 뒤로 넘겨 두 발을 잠근다','클로즈드 가드에서 상대 자세를 무너뜨린다']::text[];
update public.techniques set steps = array['상대가 내 왼쪽 무릎(니 쉴드)을 밀려고 오른손을 짚으면 내 왼손으로 그 손목을 잡는다','상체를 일으켜 내 오른팔로 상대 오른쪽 윗팔을 위에서 감아 내 왼쪽 손목을 잡는다(8자 그립)','니 쉴드로 밀어내며 상체를 내 왼쪽으로 틀어 상대 오른쪽 어깨를 바닥 쪽으로 누른다','상대 오른팔을 상대 등 뒤로 천천히 돌려 꺾고, 안 꺾이면 스윕으로 잇는다']::text[] where slug = 'kimura-from-knee-shield' and owner_id is null and steps = array['상대가 내 오른쪽 무릎(니 쉴드)을 밀려고 오른손을 짚으면 내 왼손으로 그 손목을 잡는다','내 오른팔로 상대 오른쪽 윗팔을 위에서 감아 내 왼쪽 손목을 잡는다(8자 그립)','니 쉴드로 상대를 밀어내며 몸을 내 왼쪽으로 돌려 상대 오른쪽 어깨를 바닥 쪽으로 누른다','상대 오른팔을 상대 등 뒤로 천천히 돌려 꺾고, 안 꺾이면 스윕으로 잇는다']::text[];
update public.techniques set steps = array['위 사람이 내 왼쪽 정강이(니 쉴드)를 눌러 오면 내 왼손으로 상대 오른쪽 무릎이나 골반을 민다','내 오른손은 상대 깃이나 왼쪽 어깨를 밀어 머리가 가까이 오지 못하게 한다','엉덩이를 내 오른쪽(상대에게서 먼 쪽)으로 빼서 정강이와 상대 몸 사이에 공간을 만든다','왼쪽 정강이를 상대 골반이나 배에 다시 걸어 니 쉴드로 돌아온다']::text[] where slug = 'knee-shield-retention' and owner_id is null and steps = array['위 사람이 내 오른쪽 정강이(니 쉴드)를 눌러 오면 내 오른손으로 상대 왼쪽 무릎이나 골반을 민다','내 왼손은 상대 깃이나 오른쪽 어깨를 밀어 머리가 가까이 오지 못하게 한다','엉덩이를 내 왼쪽으로 빼서 정강이와 상대 몸 사이에 공간을 만든다','오른쪽 정강이를 상대 골반이나 배에 다시 걸어 니 쉴드로 돌아온다']::text[];
