update public.techniques set steps = array['상대 오른다리를 감은 하프에서 내 왼팔 언더훅, 오른쪽 어깨와 엉덩이를 바닥에 대고 머리를 상대 오른쪽 겨드랑이 아래로 뺀다','무릎으로 일어나며 감았던 상대 오른다리를 양팔로 안는다','머리를 상대 오른쪽 옆구리에 붙이고 일어선다','안은 오른다리를 들어 올리며 밀어 넘어뜨리고 위로 올라온다']::text[] where slug = 'half-guard-to-single-leg' and owner_id is null and steps = array['상대 오른다리를 감은 하프에서 내 왼팔로 언더훅을 잡고 오른쪽 옆으로 돌아 머리를 상대 오른쪽 겨드랑이 아래로 뺀다','무릎으로 일어나며 감았던 상대 오른다리를 양팔로 안는다','머리를 상대 오른쪽 옆구리에 붙이고 일어선다','안은 오른다리를 들어 올리며 밀어 넘어뜨리고 위로 올라온다']::text[];
update public.techniques set steps = array['상대 오른다리를 감은 하프에서 내 오른쪽 어깨와 엉덩이를 바닥에 대고 내 오른팔을 상대 오른다리 바깥으로 넣어 허벅지를 안는다','내 왼손으로 상대 왼쪽 발목이나 바지 무릎을 잡는다','안은 오른다리를 들어 올리며 상대 왼쪽 발목을 당겨 중심을 뺏는다','상대가 뒤로 넘어지면 올라와 사이드나 하프 탑으로 간다']::text[] where slug = 'coyote-half-guard' and owner_id is null and steps = array['상대 오른다리를 감은 하프에서 오른쪽 옆으로 돌아 눕고 내 오른팔을 상대 오른다리 바깥으로 넣어 허벅지를 안는다','내 왼손으로 상대 왼쪽 발목이나 바지 무릎을 잡는다','안은 오른다리를 들어 올리며 상대 왼쪽 발목을 당겨 중심을 뺏는다','상대가 뒤로 넘어지면 올라와 사이드나 하프 탑으로 간다']::text[];
update public.techniques set steps = array['상대가 내 오른다리를 감은 하프가드 위에서 내 오른팔 크로스페이스, 왼팔 언더훅으로 상대를 눕힌다','걸리지 않은 내 왼발이나 손으로 상대 위쪽 무릎을 바닥 쪽으로 누른다','걸린 내 오른쪽 무릎을 앞으로 빼서 오른발목만 걸린 상태로 만든다','가슴 압박을 유지한 채 쿼터 가드에서 마지막 오른발목을 뺄 준비를 한다']::text[] where slug = 'half-guard-to-quarter-guard' and owner_id is null and steps = array['상대가 내 오른다리를 감은 하프가드 위에서 내 왼팔 크로스페이스, 오른팔 언더훅으로 상대를 눕힌다','걸리지 않은 내 왼발이나 손으로 상대 위쪽 무릎을 바닥 쪽으로 누른다','걸린 내 오른쪽 무릎을 앞으로 빼서 오른발목만 걸린 상태로 만든다','가슴 압박을 유지한 채 쿼터 가드에서 마지막 오른발목을 뺄 준비를 한다']::text[];
update public.techniques set steps = array['내 오른쪽 무릎(정강이)을 상대 오른쪽 허벅지 안쪽 위에 올리고 왼발은 뒤에 세워 미는 힘을 만든다','내 오른팔로 상대 왼팔 언더훅(또는 왼쪽 깃)을 잡아 상대 왼쪽 어깨를 바닥에 붙인다','오른쪽 정강이를 바닥까지 미끄러뜨리며 오른발까지 끝까지 빼낸다 — 다리가 다 빠지기 전에 골반을 돌리지 않는다','빠지면 골반을 돌려 가슴을 붙이고 상대 오른쪽 사이드 컨트롤로']::text[] where slug = 'knee-slice-pass' and owner_id is null and steps = array['내 오른쪽 무릎(정강이)을 상대 왼쪽 허벅지 안쪽 위에 올리고 왼발은 뒤에 세워 미는 힘을 만든다','내 오른팔로 상대 왼팔 언더훅(또는 깃)을 잡아 상대 왼쪽 어깨를 바닥에 붙인다','오른쪽 정강이를 바닥까지 미끄러뜨리며 왼다리를 끝까지 빼낸다 — 다리가 다 빠지기 전에 골반을 돌리지 않는다','빠지면 골반을 돌려 가슴을 붙이고 상대 왼쪽 사이드 컨트롤로']::text[];
update public.techniques set steps = array['내 왼손은 상대 오른쪽 무릎 뒤(바지 끝), 오른손은 상대 왼쪽 무릎 뒤(바지 끝)를 잡는다','상대 두 무릎을 내 오른쪽 바닥으로 눌러 ''죽이고'' 그쪽으로 다리를 밀어 넘긴다','발을 내 왼쪽으로 옮겨 상대 오른쪽 옆으로 돌아 들어간다','어깨를 상대 가슴에 떨어뜨리고 머리를 컨트롤해 사이드 컨트롤로']::text[] where slug = 'toreando-pass' and owner_id is null and steps = array['내 오른손은 상대 왼쪽 무릎 뒤(바지 끝), 왼손은 상대 오른쪽 무릎 뒤(바지 끝)를 잡는다','상대 두 무릎을 내 왼쪽 바닥으로 눌러 ''죽이고'' 그쪽으로 다리를 밀어 넘긴다','발을 내 오른쪽으로 옮겨 상대 왼쪽 옆으로 돌아 들어간다','어깨를 상대 가슴에 떨어뜨리고 머리를 컨트롤해 사이드 컨트롤로']::text[];
update public.techniques set steps = array['내 왼손으로 상대 오른쪽 발목(또는 바지 끝)을 잡는다','상대 오른다리를 내 오른쪽 엉덩이 옆으로 끌어와 내 허벅지 사이에 끼운다','내 왼쪽 무릎을 상대 오른쪽 엉덩이 옆에 붙여 돌지 못하게 막는다','상체를 숙여 가슴을 누르며 상대 오른쪽 사이드 컨트롤로']::text[] where slug = 'leg-drag' and owner_id is null and steps = array['내 오른손으로 상대 왼쪽 발목(또는 바지 끝)을 잡는다','상대 왼다리를 내 왼쪽 엉덩이 옆으로 끌어와 내 허벅지 사이에 끼운다','내 오른쪽 무릎을 상대 왼쪽 엉덩이 옆에 붙여 돌지 못하게 막는다','상체를 숙여 가슴을 누르며 상대 왼쪽 사이드 컨트롤로']::text[];
update public.techniques set steps = array['양팔을 상대 양다리 아래로 넣고 손을 모아 허리띠나 깃을 잡는다','상대 엉덩이를 들어 내 허벅지 위에 얹는다(스택)','어깨로 다리를 상대 머리 쪽으로 눌러 공간을 뺏는다','상대 다리를 내 오른쪽으로 떨구며 내 왼쪽으로 돌아 상대 오른쪽 사이드 컨트롤로']::text[] where slug = 'double-under-pass' and owner_id is null and steps = array['양팔을 상대 양다리 아래로 넣고 손을 모아 허리띠나 깃을 잡는다','상대 엉덩이를 들어 내 허벅지 위에 얹는다(스택)','어깨로 다리를 상대 머리 쪽으로 눌러 공간을 뺏는다','상대 다리를 내 왼쪽으로 떨구며 내 오른쪽으로 돌아 상대 왼쪽 사이드 컨트롤로']::text[];
update public.techniques set steps = array['상대가 다리를 높이 들고 버티면 내 왼손으로 상대 무릎을 눌러 다리를 내 오른쪽으로 치운다','상대 몸통 오른쪽 옆(내 왼쪽) 바닥에 두 손을 짚는다','다리를 차올려 옆돌기하듯 상대 다리 위를 넘어 상대 오른쪽에 착지한다','착지하자마자 가슴을 상대 가슴에 붙여 누른다','상대 오른쪽에서 사이드 컨트롤로 끝난다']::text[] where slug = 'cartwheel-pass' and owner_id is null and steps = array['상대가 다리를 높이 들고 버티면 내 오른손으로 상대 무릎을 눌러 다리를 내 왼쪽으로 치운다','상대 몸통 왼쪽 옆(내 오른쪽) 바닥에 두 손을 짚는다','다리를 차올려 옆돌기하듯 상대 다리 위를 넘어 상대 왼쪽에 착지한다','착지하자마자 가슴을 상대 가슴에 붙여 누른다','상대 왼쪽에서 사이드 컨트롤로 끝난다']::text[];
update public.techniques set steps = array['상대가 내 오른다리를 걸어 누르고 내 오른쪽으로 넘어오려 할 때','걸린 내 오른다리를 빼며 엉덩이를 뒤로 뺀다','내 오른쪽 옆구리를 바닥에 대고 위쪽 내 왼쪽 무릎을 상대 배 앞에 세워 쉴드를 만든다','빼낸 아래쪽 내 오른다리로 상대 오른다리를 감는다','니 쉴드 하프가드로 거리를 지킨다']::text[] where slug = 'shin-shield-recovery' and owner_id is null and steps = array['상대가 내 왼다리를 걸어 누르고 내 오른쪽으로 넘어오려 할 때','걸린 내 왼다리를 빼며 엉덩이를 뒤로 뺀다','내 오른쪽 옆구리를 바닥에 대고 빼낸 왼쪽 무릎을 상대 배 앞에 세워 쉴드를 만든다','아래쪽 내 오른다리로 상대 왼다리를 감는다','니 쉴드 하프가드로 거리를 지킨다']::text[];
update public.techniques set steps = array['상대가 내 오른다리를 걸어 누르고 내 오른쪽으로 넘어오려 할 때','걸린 내 오른쪽 무릎을 세워 안쪽으로 돌려 훅을 푼다','엉덩이를 내 왼쪽으로 빼며 내 오른다리를 빼낸다','빼낸 내 오른다리로 상대 오른다리를 감아 하프가드를 잡는다','내 왼팔로 상대 오른팔 언더훅을 노린다']::text[] where slug = 'escape-leg-hook' and owner_id is null and steps = array['상대가 내 왼다리를 걸어 누르고 있을 때','걸린 내 왼쪽 무릎을 상대 쪽(내 오른쪽)으로 돌려 훅을 푼다','엉덩이를 빼며 내 왼다리를 빼낸다','빼낸 내 왼다리로 상대 왼다리를 감아 하프가드를 잡는다','내 왼팔로 언더훅을 노린다']::text[];
update public.techniques set steps = array['상대 오른쪽에서 사이드를 잡고 내 왼팔 크로스페이스를 상대 머리 뒤로 깊게 넣는다','내 왼쪽 어깨를 상대 턱 오른쪽에 대고 상대 고개를 상대 왼쪽으로 민다','엉덩이는 낮추고 발끝으로 버텨 체중을 왼쪽 어깨에 싣는다','상대가 밀어내려고 팔을 뻗으면 그 팔을 노린다 → 기무라 · 아메리카나 · 마운트']::text[] where slug = 'side-control-to-shoulder-of-justice' and owner_id is null and steps = array['상대 왼쪽에서 사이드를 잡고 내 오른팔 크로스페이스를 상대 머리 뒤로 깊게 넣는다','내 오른쪽 어깨를 상대 턱 왼쪽에 대고 상대 고개를 상대 오른쪽으로 민다','엉덩이는 낮추고 발끝으로 버텨 체중을 오른쪽 어깨에 싣는다','상대가 밀어내려고 팔을 뻗으면 그 팔을 노린다 → 기무라 · 아메리카나 · 마운트']::text[];
update public.techniques set steps = array['상대 오른쪽에서 상대 왼팔을 목 앞으로 감아, 머리 뒤로 넣은 내 왼손으로 상대 왼쪽 손목을 잡는다','가슴으로 상대 오른쪽 어깨를 눌러 등을 바닥에 붙인다','상대가 팔을 빼려 하면 왼쪽 손목을 내 쪽으로 당겨 팔꿈치를 목에 붙인다','무게를 머리 쪽에 둔 채 다음 공격을 고른다 → 기무라 · 암바 · 백 테이크']::text[] where slug = 'gift-wrap-maintenance' and owner_id is null and steps = array['상대 왼쪽에서 상대 오른팔을 목 앞으로 감아, 머리 뒤로 넣은 내 오른손으로 상대 오른쪽 손목을 잡는다','가슴으로 상대 왼쪽 어깨를 눌러 등을 바닥에 붙인다','상대가 팔을 빼려 하면 오른쪽 손목을 내 쪽으로 당겨 팔꿈치를 목에 붙인다','무게를 머리 쪽에 둔 채 다음 공격을 고른다 → 기무라 · 암바 · 백 테이크']::text[];
update public.techniques set steps = array['하이 마운트에서 상대 오른팔은 안쪽에 두고 내 오른다리를 상대 왼 어깨 너머 목 뒤로 넘긴다','넘긴 오른 발목을 내 왼 무릎 뒤에 걸어 잠근다','상대 머리를 당기며 앞으로 몸을 낮추거나 뒤로 굴러 가드 트라이앵글로 간다','다리를 조여 마무리한다']::text[] where slug = 'mounted-triangle' and owner_id is null and steps = array['하이 마운트에서 상대 오른팔은 안쪽에 두고 내 왼다리를 상대 목 뒤로 넘긴다','넘긴 왼 발목을 내 오른 무릎 뒤에 걸어 잠근다','상대 머리를 당기며 앞으로 몸을 낮추거나 뒤로 굴러 가드 트라이앵글로 간다','다리를 조여 마무리한다']::text[];
update public.techniques set steps = array['S 마운트에서 상대 오른팔은 내 다리 안쪽에, 왼팔은 바깥에 두게 만든다','상대 왼 겨드랑이 쪽에 접어 둔 내 오른다리를 상대 왼 어깨 너머 목 뒤로 넘긴다','넘긴 오른 발목을 내 왼 무릎 뒤에 걸어 잠근다','상대 머리를 끌어안고 몸을 낮춰 상대 오른 어깨를 목 쪽으로 밀어 넣는다','다리를 조이며 마무리하거나 뒤로 굴러 가드 트라이앵글로 간다']::text[] where slug = 's-mount-to-mounted-triangle' and owner_id is null and steps = array['S 마운트에서 상대 오른팔은 내 다리 안쪽에, 왼팔은 바깥에 두게 만든다','상대 머리 오른쪽에 세운 내 왼다리를 상대 목 뒤로 넘겨 왼 발목을 오른 무릎 뒤에 건다','상대 머리를 끌어안고 앞으로 몸을 낮춰 상대 오른 어깨를 목 쪽으로 밀어 넣는다','다리를 조이며 마무리하거나 뒤로 굴러 가드 트라이앵글로 간다']::text[];
update public.techniques set steps = array['턱을 당기고 두 손으로 내 오른쪽 어깨 위로 오는 상대 오른팔부터 막는다','내 오른쪽 옆구리에서 잠긴 상대 왼발목 위에 내 오른발을 얹어 눌러 잠금을 푼다','엉덩이를 내 오른쪽 바닥으로 미끄러뜨려 등을 매트에 붙인다','몸을 내 왼쪽(상대 쪽)으로 돌리며 상대 오른다리를 내 두 다리로 감는다','하프가드']::text[] where slug = 'body-triangle-escape-to-half-guard' and owner_id is null and steps = array['턱을 당기고 두 손으로 내 오른쪽 어깨 위로 오는 상대 오른팔부터 막는다','내 왼쪽 옆구리에 걸린 상대 오른발목 위에 내 왼발을 얹어 눌러 잠금을 푼다','엉덩이를 내 오른쪽 바닥으로 미끄러뜨려 등을 매트에 붙인다','몸을 내 왼쪽(상대 쪽)으로 돌리며 상대 오른다리를 내 두 다리로 감는다','하프가드']::text[];
update public.techniques set steps = array['상대가 내 왼다리를 하프가드처럼 감아도 내 오른쪽 무릎은 바닥에 붙이고 엉덩이를 낮춰 버틴다','내 왼팔로 크로스페이스해 상대 얼굴을 상대 왼쪽(내 오른쪽)으로 돌린다','내 오른발로 상대 발목을 밀어 내리거나 내 왼쪽 무릎을 세워 왼다리를 빼낸다','빼낸 왼다리를 바닥에 내려 풀 마운트를 완성한다']::text[] where slug = '3-4-mount' and owner_id is null and steps = array['상대가 내 오른다리를 하프가드처럼 감아도 내 왼쪽 무릎은 바닥에 붙이고 엉덩이를 낮춰 버틴다','내 오른팔로 크로스페이스해 상대 얼굴을 상대 오른쪽(내 왼쪽)으로 돌린다','내 왼발로 상대 발목을 밀어 내리거나 내 오른쪽 무릎을 세워 오른다리를 빼낸다','빼낸 오른다리를 바닥에 내려 풀 마운트를 완성한다']::text[];
update public.techniques set steps = array['내가 상대 왼다리를 감은 3/4 마운트 기준 — 내 오른쪽 옆으로 돌며 왼팔 팔뚝으로 상대 왼쪽 골반을 막는다','엉덩이를 내 왼쪽으로 빼며(쉬림프) 상대 왼다리와 내 몸 사이 공간을 만든다','그 공간에 내 왼쪽 무릎을 넣어 니 쉴드를 세우거나 내 오른팔로 상대 왼팔 아래 언더훅을 잡는다','하프가드를 굳히거나 가드를 회복한다']::text[] where slug = 'elbow-escape-from-3-4-mount' and owner_id is null and steps = array['내가 상대 오른다리를 감은 3/4 마운트 기준 — 내 왼쪽 옆으로 돌며 오른팔 팔뚝으로 상대 오른쪽 골반을 막는다','엉덩이를 내 오른쪽으로 빼며(쉬림프) 상대 오른다리와 내 몸 사이 공간을 만든다','그 공간에 내 오른쪽 무릎을 넣어 니 쉴드를 세우거나 내 왼팔로 상대 오른팔 아래 언더훅을 잡는다','하프가드를 굳히거나 가드를 회복한다']::text[];
update public.techniques set steps = array['엉덩이를 낮추고 양 무릎을 상대 몸에 바짝 붙인다','상대가 내 오른쪽으로 브릿지하면 내 오른손을 넓게 짚어 균형을 잡는다(왼쪽이면 왼손)','상대가 엉덩이를 내 오른쪽으로 빼면 내 오른 무릎으로 골반을 막고 다시 가운데로 앉는다','상대가 많이 움직이면 양발을 상대 양다리 안쪽에 감아(그레이프바인) 낮게 버틴다','상대 팔이 떨어지면 양 무릎을 겨드랑이 쪽으로 걸어 올려 하이 마운트로 간다']::text[] where slug = 'mount-maintain' and owner_id is null and steps = array['엉덩이를 낮추고 양 무릎을 상대 몸에 바짝 붙인다','상대가 내 오른쪽으로 브릿지하면 내 오른손을 넓게 짚어 균형을 잡는다(왼쪽이면 왼손)','상대가 엉덩이를 내 왼쪽으로 빼면 내 왼 무릎으로 골반을 막고 다시 가운데로 앉는다','상대가 많이 움직이면 양발을 상대 양다리 안쪽에 감아(그레이프바인) 낮게 버틴다','상대 팔이 떨어지면 양 무릎을 겨드랑이 쪽으로 걸어 올려 하이 마운트로 간다']::text[];
update public.techniques set steps = array['상대가 내 왼쪽 옆에 있을 때, 터틀에서 두 팔로 상대 왼다리를 감싸 가슴에 붙인다','내 머리를 상대 왼쪽 옆구리에 붙이고 내 왼발을 바닥에 세운다','상대 왼다리를 잡은 채 베이스를 잡고 일어선다','상대 왼다리를 들어 올려 넘어뜨리고 탑 포지션을 잡는다']::text[] where slug = 'single-leg-from-turtle' and owner_id is null and steps = array['상대가 내 오른쪽 옆에 있을 때, 터틀에서 두 팔로 상대 오른다리를 감싸 가슴에 붙인다','내 머리를 상대 오른쪽 옆구리에 붙이고 내 오른발을 바닥에 세운다','상대 오른다리를 잡은 채 베이스를 잡고 일어선다','상대 오른다리를 들어 올려 넘어뜨리고 탑 포지션을 잡는다']::text[];
update public.techniques set steps = array['상대가 내 등 뒤에서 내 왼쪽 허벅지 안에 훅을 넣으면 오른쪽 팔꿈치를 오른쪽 무릎에 붙여 두 번째 훅을 막는다','내 왼손으로 훅 들어온 상대 왼발을 잡아 내 왼쪽 무릎 아래로 밀어 낸다','훅이 빠지면 상대 몸에서 먼 내 오른쪽으로 엉덩이를 앉힌다','다리를 상대 쪽으로 돌려 가드를 되찾는다']::text[] where slug = 'clear-hook-from-turtle' and owner_id is null and steps = array['상대가 내 등 뒤에서 내 오른쪽 허벅지 안에 훅을 넣으면 왼쪽 팔꿈치를 왼쪽 무릎에 붙여 두 번째 훅을 막는다','내 오른손으로 훅 들어온 상대 오른발을 잡아 내 오른쪽 무릎 아래로 밀어 낸다','훅이 빠지면 상대 몸에서 먼 내 왼쪽으로 엉덩이를 앉힌다','다리를 상대 쪽으로 돌려 가드를 되찾는다']::text[];
update public.techniques set steps = array['상대가 내 왼쪽에서 내 왼팔을 다리로 가두면 왼쪽 팔꿈치를 굽혀 왼손을 내 몸에 붙인다','상대가 있는 내 왼쪽으로 몸을 돌리며 왼쪽 무릎을 바닥에 댄다','상대 다리에 끼인 내 왼팔을 아래로 빼며 터틀로 돌아간다','엉덩이를 내 오른쪽으로 빼고 다리를 상대 쪽으로 돌려 가드를 되찾는다']::text[] where slug = 'escape-crucifix' and owner_id is null and steps = array['상대가 내 오른쪽에서 내 오른팔을 다리로 가두면 오른쪽 팔꿈치를 굽혀 오른손을 내 몸에 붙인다','상대가 있는 내 오른쪽으로 몸을 돌리며 오른쪽 무릎을 바닥에 댄다','상대 다리에 끼인 내 오른팔을 아래로 빼며 터틀로 돌아간다','엉덩이를 내 왼쪽으로 빼고 다리를 상대 쪽으로 돌려 가드를 되찾는다']::text[];
update public.techniques set steps = array['상대 왼팔을 내 다리로 가둔 크루시픽스에서 내 오른손으로 상대 오른쪽 손목을 잡는다','내 왼팔을 상대 오른팔 아래로 넣어 내 오른손목을 잡는다(8자 그립)','상대 오른쪽 팔꿈치가 90도로 굽은 상태를 유지한다','상대 오른쪽 손목을 상대 등 쪽으로 천천히 돌리며 조인다','탭하면 바로 푼다']::text[] where slug = 'kimura-from-crucifix' and owner_id is null and steps = array['상대 오른팔을 내 다리로 가둔 크루시픽스에서 내 왼손으로 상대 왼쪽 손목을 잡는다','내 오른팔을 상대 왼팔 아래로 넣어 내 왼손목을 잡는다(8자 그립)','상대 왼쪽 팔꿈치가 90도로 굽은 상태를 유지한다','상대 왼쪽 손목을 상대 등 쪽으로 천천히 돌리며 조인다','탭하면 바로 푼다']::text[];
update public.techniques set steps = array['터틀한 상대 왼쪽 뒤 옆에서 가슴을 상대 등에 얹는다','내 왼발을 상대 왼쪽 허벅지 안쪽에 깊게 넣어 첫 훅을 건다','내 오른손은 상대 오른쪽 깃(노기는 겨드랑이)을, 왼손은 띠를 잡는다','엉덩이를 상대 엉덩이 위에 무겁게 올려 상대가 앉거나 돌지 못하게 누른다','상대가 버티면 상대 왼쪽으로 무게를 실어 눕히고 내 오른발 훅을 상대 오른쪽 허벅지 안쪽에 넣어 백 컨트롤로 간다']::text[] where slug = 'turtle-to-rodeo-ride' and owner_id is null and steps = array['터틀한 상대 왼쪽 뒤 옆에서 가슴을 상대 등에 얹는다','내 오른발을 상대 왼쪽 허벅지 안쪽에 깊게 넣어 첫 훅을 건다','내 오른손은 상대 오른쪽 깃(노기는 겨드랑이)을, 왼손은 띠를 잡는다','엉덩이를 상대 엉덩이 위에 무겁게 올려 상대가 앉거나 돌지 못하게 누른다','상대가 버티면 상대 왼쪽으로 무게를 실어 눕히고 왼발 두 번째 훅을 넣어 백 컨트롤로 간다']::text[];
